#include "Mapper073.h"
#include "../state_io.h"
#include <algorithm>
void Mapper073::reset(){reloadValue=counter=prgPage=0;enabled=enableOnAck=mode8Bit=irqActive=false;}
bool Mapper073::cpuMapRead(uint16_t a,uint32_t&m){if(a<0x8000)return false;uint16_t c=std::max<uint16_t>(1,prgBanks);uint16_t p=(a<0xC000)?prgPage:uint16_t(c-1);m=uint32_t(p%c)*0x4000u+(a&0x3FFFu);return true;}
bool Mapper073::cpuMapWrite(uint16_t a,uint32_t&m,uint8_t d){if(a<0x8000)return false;switch(a&0xF000u){case 0x8000:reloadValue=uint16_t((reloadValue&0xFFF0u)|(d&0x0Fu));break;case 0x9000:reloadValue=uint16_t((reloadValue&0xFF0Fu)|((d&0x0Fu)<<4));break;case 0xA000:reloadValue=uint16_t((reloadValue&0xF0FFu)|((d&0x0Fu)<<8));break;case 0xB000:reloadValue=uint16_t((reloadValue&0x0FFFu)|((d&0x0Fu)<<12));break;case 0xC000:enabled=(d&2u)!=0;if(enabled)counter=reloadValue;mode8Bit=(d&4u)!=0;enableOnAck=(d&1u)!=0;irqActive=false;break;case 0xD000:irqActive=false;enabled=enableOnAck;break;case 0xF000:prgPage=uint16_t(d&7u);break;default:break;}m=0;return true;}
bool Mapper073::ppuMapRead(uint16_t a,uint32_t&m){if(a>0x1FFF)return false;m=a;return true;}bool Mapper073::ppuMapWrite(uint16_t a,uint32_t&m,uint8_t){if(a>0x1FFF||chrBanks!=0)return false;m=a;return true;}
void Mapper073::cpuClock(){if(!enabled)return;if(mode8Bit){uint8_t v=uint8_t(counter);++v;if(v==0){v=uint8_t(reloadValue);irqActive=true;}counter=uint16_t((counter&0xFF00u)|v);}else{++counter;if(counter==0){counter=reloadValue;irqActive=true;}}}
void Mapper073::saveState(std::vector<uint8_t>&o)const{using namespace ciphernes_state;write_u16(o,reloadValue);write_u16(o,counter);write_u16(o,prgPage);write_bool(o,enabled);write_bool(o,enableOnAck);write_bool(o,mode8Bit);write_bool(o,irqActive);}bool Mapper073::loadState(const uint8_t*&p,const uint8_t*e){using namespace ciphernes_state;return read_u16(p,e,reloadValue)&&read_u16(p,e,counter)&&read_u16(p,e,prgPage)&&read_bool(p,e,enabled)&&read_bool(p,e,enableOnAck)&&read_bool(p,e,mode8Bit)&&read_bool(p,e,irqActive);}
